import XCTest
protocol MinuteReading { var minute: Int { get } }
struct FixedMinute: MinuteReading { let minute: Int }
struct HeatingSchedule {
    let clock: any MinuteReading
    func isNight() -> Bool { clock.minute >= 22 * 60 }
}
final class HeatingTests: XCTestCase {
    func testBoundary() {
        let before = HeatingSchedule(clock: FixedMinute(minute: 1319))
        let at = HeatingSchedule(clock: FixedMinute(minute: 1320))
        XCTAssertFalse(before.isNight())
        XCTAssertTrue(at.isNight())
    }
}

Время стало управляемым входом. Два соседних значения ловят неверный > вместо >= без настоящих часов.
